1	package com.example.starter.damage.api;
2	
3	import com.example.starter.damage.dto.Requests.ApprovalRequest;
4	import com.example.starter.damage.dto.Requests.CloseRequest;
5	import com.example.starter.damage.dto.Requests.CompletionRequest;
6	import com.example.starter.damage.dto.Requests.EstimateRequest;
7	import com.example.starter.damage.dto.Requests.PhotoRequest;
8	import com.example.starter.damage.dto.Requests.RegisterRequest;
9	import com.example.starter.damage.dto.Requests.ReinspectionRequest;
10	import com.example.starter.damage.dto.Requests.SurveyRequest;
11	import com.example.starter.damage.dto.Views.ApprovalView;
12	import com.example.starter.damage.dto.Views.CaseDetailView;
13	import com.example.starter.damage.dto.Views.CaseView;
14	import com.example.starter.damage.dto.Views.CompletionView;
15	import com.example.starter.damage.dto.Views.EstimateView;
16	import com.example.starter.damage.dto.Views.PhotoResult;
17	import com.example.starter.damage.service.DamageCaseService;
18	import jakarta.validation.Valid;
19	import org.springframework.http.HttpStatus;
20	import org.springframework.web.bind.annotation.GetMapping;
21	import org.springframework.web.bind.annotation.PathVariable;
22	import org.springframework.web.bind.annotation.PostMapping;
23	import org.springframework.web.bind.annotation.RequestBody;
24	import org.springframework.web.bind.annotation.RequestMapping;
25	import org.springframework.web.bind.annotation.ResponseStatus;
26	import org.springframework.web.bind.annotation.RestController;
27	
28	/**
29	 * 集装箱残损检验与修理放行 API。
30	 * 流转：到港登记 → 检验 → 估价 → 修理批复 → 复检 → 放行/全损。
31	 */
32	@RestController
33	@RequestMapping("/api/cases")
34	public class DamageCaseController {
35	
36	    private final DamageCaseService service;
37	
38	    public DamageCaseController(DamageCaseService service) {
39	        this.service = service;
40	    }
41	
42	    /** 到港登记 */
43	    @PostMapping
44	    @ResponseStatus(HttpStatus.CREATED)
45	    public CaseView register(@Valid @RequestBody RegisterRequest request) {
46	        return service.register(request);
47	    }
48	
49	    /** 检验：按合成 IICL 代码登记残损项 */
50	    @PostMapping("/{caseId}/survey")
51	    public CaseDetailView survey(@PathVariable long caseId, @Valid @RequestBody SurveyRequest request) {
52	        return service.survey(caseId, request);
53	    }
54	
55	    /** 估价：生成新估价版本 */
56	    @PostMapping("/{caseId}/estimates")
57	    public EstimateView estimate(@PathVariable long caseId, @Valid @RequestBody EstimateRequest request) {
58	        return service.estimate(caseId, request);
59	    }
60	
61	    /** 修理批复 */
62	    @PostMapping("/{caseId}/approvals")
63	    public ApprovalView approve(@PathVariable long caseId, @Valid @RequestBody ApprovalRequest request) {
64	        return service.approve(caseId, request);
65	    }
66	
67	    /** 修理（或返修）完工 */
68	    @PostMapping("/{caseId}/repair-completions")
69	    public CompletionView completeRepair(@PathVariable long caseId, @Valid @RequestBody CompletionRequest request) {
70	        return service.completeRepair(caseId, request);
71	    }
72	
73	    /** 复检 */
74	    @PostMapping("/{caseId}/reinspections")
75	    public CaseView reinspect(@PathVariable long caseId, @Valid @RequestBody ReinspectionRequest request) {
76	        return service.reinspect(caseId, request);
77	    }
78	
79	    /** 结案：修理放行/全损，终态 */
80	    @PostMapping("/{caseId}/close")
81	    public CaseView close(@PathVariable long caseId, @Valid @RequestBody CloseRequest request) {
82	        return service.close(caseId, request);
83	    }
84	
85	    /** 检验照片登记；结案后迟到照片只记迟到事件 */
86	    @PostMapping("/{caseId}/photos")
87	    public PhotoResult photo(@PathVariable long caseId, @Valid @RequestBody PhotoRequest request) {
88	        return service.photo(caseId, request);
89	    }
90	
91	    /** 案件全量明细：残损清单、估价版本与修理链 */
92	    @GetMapping("/{caseId}")
93	    public CaseDetailView detail(@PathVariable long caseId) {
94	        return service.detail(caseId);
95	    }
96	}
