1	package com.example.starter.damage.service;
2	
3	import com.example.starter.damage.api.ApiException;
4	import com.example.starter.damage.store.IdempotencyRepository;
5	import com.example.starter.damage.store.IdempotencyRepository.IdemRow;
6	import com.fasterxml.jackson.databind.ObjectMapper;
7	import org.springframework.dao.DuplicateKeyException;
8	import org.springframework.stereotype.Component;
9	
10	import java.nio.charset.StandardCharsets;
11	import java.security.MessageDigest;
12	import java.security.NoSuchAlgorithmException;
13	import java.time.Clock;
14	import java.time.LocalDateTime;
15	import java.util.Optional;
16	import java.util.function.Supplier;
17	
18	/**
19	 * 幂等执行器：requestId 占位插入保证并发唯一受理；
20	 * 指纹覆盖 requestId 与全部业务字段，同键同参返回首次结果，同键异参返回 409。
21	 */
22	@Component
23	public class IdempotencyExecutor {
24	
25	    private static final long WAIT_TIMEOUT_MILLIS = 10_000;
26	    private static final long POLL_INTERVAL_MILLIS = 50;
27	
28	    private final IdempotencyRepository repository;
29	    private final ObjectMapper objectMapper;
30	    private final Clock clock;
31	
32	    public IdempotencyExecutor(IdempotencyRepository repository, ObjectMapper objectMapper, Clock clock) {
33	        this.repository = repository;
34	        this.objectMapper = objectMapper;
35	        this.clock = clock;
36	    }
37	
38	    /**
39	     * 以幂等方式执行写操作。
40	     *
41	     * @param endpoint 入口标识（参与指纹计算）
42	     * @param requestId 幂等请求 ID
43	     * @param payload 全部业务字段（参与指纹计算）
44	     * @param type 响应类型
45	     * @param action 业务动作（在事务内执行，并负责写入完成标记）
46	     * @return 首次执行结果或重放结果
47	     */
48	    public <T> T execute(String endpoint, String requestId, Object payload, Class<T> type, Supplier<T> action) {
49	        String fingerprint = fingerprint(endpoint, requestId, payload);
50	        for (int attempt = 0; attempt < 3; attempt++) {
51	            Optional<IdemRow> existing = repository.find(requestId);
52	            if (existing.isEmpty()) {
53	                try {
54	                    repository.insertInProgress(requestId, endpoint, fingerprint, LocalDateTime.now(clock));
55	                } catch (DuplicateKeyException e) {
56	                    continue; // 并发下由主键仲裁，重新读取
57	                }
58	                try {
59	                    return action.get();
60	                } catch (RuntimeException e) {
61	                    repository.delete(requestId); // 业务失败释放占位，允许重试
62	                    throw e;
63	                }
64	            }
65	            IdemRow row = existing.get();
66	            if (!row.fingerprint().equals(fingerprint)) {
67	                throw ApiException.conflict("相同 requestId 的请求参数不一致，已拒绝");
68	            }
69	            if (!"COMPLETED".equals(row.status())) {
70	                row = awaitCompletion(requestId);
71	                if (row == null) {
