36	/**
37	 * 残损检验业务流测试：使用真实 H2（MySQL 兼容模式）验证状态机、
38	 * 30% 全损阈值、批复 7 个自然日有效期、返修一次限制、判定唯一与幂等语义。
39	 */
40	@SpringBootTest
41	class DamageFlowServiceTest {
42	
