51	        jdbc.update("delete from case_event");
52	        jdbc.update("delete from reinspection");
53	        jdbc.update("delete from repair_completion");
54	        jdbc.update("delete from repair_approval");
55	        jdbc.update("delete from estimate");
56	        jdbc.update("delete from damage_item");
57	        jdbc.update("delete from damage_case");
58	        jdbc.update("delete from idempotency_record");
59	    }
60	
61	    private long newCase(String containerNo, String containerValue) {
62	        return service.register(new RegisterRequest(
63	                "reg-" + UUID.randomUUID(), containerNo, new BigDecimal(containerValue))).id();
64	    }
65	
66	    private void survey(long caseId, String requestId, DamageItemInput... items) {
67	        service.survey(caseId, new SurveyRequest(requestId, List.of(items)));
68	    }
69	
70	    private DamageItemInput item(String repairCost) {
71	        return new DamageItemInput("DN", "侧板", "凹痕一处", Responsibility.OWNER, new BigDecimal(repairCost));
72	    }
73	
74	    private DamageItemInput terminalItem(String repairCost) {
75	        return new DamageItemInput("BR", "底梁", "弯曲变形", Responsibility.TERMINAL, new BigDecimal(repairCost));
76	    }
77	
78	    private void approveAndComplete(long caseId, LocalDate approvalDate, LocalDate completionDate) {
79	        service.approve(caseId, new ApprovalRequest("ap-" + UUID.randomUUID(), approvalDate));
80	        service.completeRepair(caseId, new CompletionRequest("cp-" + UUID.randomUUID(), completionDate));
81	    }
82	
83	    @Test
84	    void exactlyThirtyPercentIsRepair() {
85	        long caseId = newCase("TEMU1000001", "10000.00");
86	        survey(caseId, "svy-" + UUID.randomUUID(), item("3000.00"));
87	
88	        EstimateView estimate = service.estimate(caseId, new EstimateRequest("est-" + UUID.randomUUID()));
89	
90	        assertThat(estimate.determination()).isEqualTo(Determination.REPAIR);
91	        assertThat(estimate.totalCost()).isEqualByComparingTo("3000.00");
92	        assertThat(estimate.version()).isEqualTo(1);
93	    }
94	
95	    @Test
96	    void overThirtyPercentIsTotalLossAndCannotApproveRepair() {
97	        long caseId = newCase("TEMU1000002", "10000.00");
98	        survey(caseId, "svy-" + UUID.randomUUID(), item("3000.01"));
99	
100	        EstimateView estimate = service.estimate(caseId, new EstimateRequest("est-" + UUID.randomUUID()));
101	        assertThat(estimate.determination()).isEqualTo(Determination.TOTAL_LOSS);
102	
103	        // 判定唯一：全损案件不得批复修理
104	        assertThatThrownBy(() -> service.approve(caseId, new ApprovalRequest("ap-x1", LocalDate.of(2026, 9, 1))))
105	                .isInstanceOf(ApiException.class)
106	                .satisfies(e -> assertThat(((ApiException) e).status()).isEqualTo(HttpStatus.CONFLICT));
107	
108	        // 全损结案为终态
109	        CaseView closed = service.close(caseId, new CloseRequest("cl-" + UUID.randomUUID()));
110	        assertThat(closed.status()).isEqualTo(CaseStatus.TOTAL_LOSS);
111	        assertThat(closed.closedAt()).isNotNull();
112	    }
113	
114	    @Test
115	    void repairDeterminationCannotCloseAsTotalLoss() {
116	        long caseId = newCase("TEMU1000003", "10000.00");
117	        survey(caseId, "svy-" + UUID.randomUUID(), item("1000.00"));
118	        EstimateView estimate = service.estimate(caseId, new EstimateRequest("est-" + UUID.randomUUID()));
119	        assertThat(estimate.determination()).isEqualTo(Determination.REPAIR);
120	        service.approve(caseId, new ApprovalRequest("ap-" + UUID.randomUUID(), LocalDate.of(2026, 9, 1)));
121	
122	        // 修理判定案件在批复后不得直接按全损结案（判定唯一）
123	        assertThatThrownBy(() -> service.close(caseId, new CloseRequest("cl-x1")))
124	                .isInstanceOf(ApiException.class)
125	                .satisfies(e -> assertThat(((ApiException) e).status()).isEqualTo(HttpStatus.CONFLICT));
126	    }
127	
128	    @Test
129	    void completionOnExactDaySevenIsValid() {
130	        long caseId = newCase("TEMU1000004", "10000.00");
131	        survey(caseId, "svy-" + UUID.randomUUID(), item("1000.00"));
132	        service.estimate(caseId, new EstimateRequest("est-" + UUID.randomUUID()));
133	        service.approve(caseId, new ApprovalRequest("ap-" + UUID.randomUUID(), LocalDate.of(2026, 9, 1)));
134	
135	        // 批复日 9-01 为第 1 日，9-07 恰为第 7 日，完工有效
136	        var completion = service.completeRepair(caseId,
137	                new CompletionRequest("cp-" + UUID.randomUUID(), LocalDate.of(2026, 9, 7)));
138	
139	        assertThat(completion.completionDate()).isEqualTo(LocalDate.of(2026, 9, 7));
140	        assertThat(completion.rework()).isFalse();
141	        assertThat(service.detail(caseId).caseInfo().status()).isEqualTo(CaseStatus.REPAIR_DONE);
142	    }
143	
144	    @Test
145	    void overdueCompletionRejectedAndReestimateRequired() {
146	        long caseId = newCase("TEMU1000005", "10000.00");
147	        survey(caseId, "svy-" + UUID.randomUUID(), item("1000.00"));
148	        service.estimate(caseId, new EstimateRequest("est-" + UUID.randomUUID()));
149	        service.approve(caseId, new ApprovalRequest("ap-" + UUID.randomUUID(), LocalDate.of(2026, 9, 1)));
150	
151	        // 9-08 为第 8 日，逾期须重新估价
152	        assertThatThrownBy(() -> service.completeRepair(caseId,
153	                new CompletionRequest("cp-x1", LocalDate.of(2026, 9, 8))))
154	                .isInstanceOf(ApiException.class)
155	                .satisfies(e -> assertThat(((ApiException) e).status()).isEqualTo(HttpStatus.CONFLICT))
156	                .hasMessageContaining("逾期");
157	
158	        // 重新估价产生新版本，旧批复失效
159	        EstimateView second = service.estimate(caseId, new EstimateRequest("est-" + UUID.randomUUID()));
160	        assertThat(second.version()).isEqualTo(2);
161	        CaseDetailView detail = service.detail(caseId);
162	        assertThat(detail.estimates()).hasSize(2);
163	        assertThat(detail.estimates().get(0).status()).isEqualTo("SUPERSEDED");
164	        assertThat(detail.estimates().get(1).status()).isEqualTo("CURRENT");
165	        assertThat(detail.approvals().get(0).status()).isEqualTo("SUPERSEDED");
166	
167	        // 重新批复后在有效期内完工
168	        approveAndComplete(caseId, LocalDate.of(2026, 9, 8), LocalDate.of(2026, 9, 14));
169	        assertThat(service.detail(caseId).caseInfo().status()).isEqualTo(CaseStatus.REPAIR_DONE);
170	    }
171	
172	    @Test
173	    void reworkAllowedOnlyOnceThenTotalLoss() {
174	        long caseId = newCase("TEMU1000006", "10000.00");
175	        survey(caseId, "svy-" + UUID.randomUUID(), item("1000.00"));
176	        service.estimate(caseId, new EstimateRequest("est-" + UUID.randomUUID()));
177	        approveAndComplete(caseId, LocalDate.of(2026, 9, 1), LocalDate.of(2026, 9, 3));
178	
179	        // 首次复检不合格 → 返修一次
180	        CaseView afterFirstFail = service.reinspect(caseId, new ReinspectionRequest("ri-" + UUID.randomUUID(), false));
181	        assertThat(afterFirstFail.status()).isEqualTo(CaseStatus.REWORK);
182	        assertThat(afterFirstFail.reworkCount()).isEqualTo(1);
183	
184	        // 返修完工
185	        var reworkCompletion = service.completeRepair(caseId,
186	                new CompletionRequest("cp-" + UUID.randomUUID(), LocalDate.of(2026, 9, 5)));
187	        assertThat(reworkCompletion.rework()).isTrue();
188	
189	        // 返修后复检仍不合格 → 转全损评估
190	        CaseView afterSecondFail = service.reinspect(caseId, new ReinspectionRequest("ri-" + UUID.randomUUID(), false));
191	        assertThat(afterSecondFail.status()).isEqualTo(CaseStatus.TOTAL_LOSS_PENDING);
192	        assertThat(afterSecondFail.determination()).isEqualTo(Determination.TOTAL_LOSS);
193	
194	        CaseView closed = service.close(caseId, new CloseRequest("cl-" + UUID.randomUUID()));
195	        assertThat(closed.status()).isEqualTo(CaseStatus.TOTAL_LOSS);
196	    }
