198	    @Test
199	    void fullRepairFlowReleasesAndFreesContainer() {
200	        long caseId = newCase("TEMU1000007", "10000.00");
201	        survey(caseId, "svy-" + UUID.randomUUID(), item("1000.00"), terminalItem("500.00"));
202	        EstimateView estimate = service.estimate(caseId, new EstimateRequest("est-" + UUID.randomUUID()));
203	        assertThat(estimate.totalCost()).isEqualByComparingTo("1500.00");
204	        approveAndComplete(caseId, LocalDate.of(2026, 9, 1), LocalDate.of(2026, 9, 2));
205	
206	        CaseView passed = service.reinspect(caseId, new ReinspectionRequest("ri-" + UUID.randomUUID(), true));
207	        assertThat(passed.status()).isEqualTo(CaseStatus.REPAIR_PASSED);
208	
209	        // 放行与结案同事务完成
210	        CaseView closed = service.close(caseId, new CloseRequest("cl-" + UUID.randomUUID()));
211	        assertThat(closed.status()).isEqualTo(CaseStatus.RELEASED);
212	        assertThat(closed.closedAt()).isNotNull();
213	
214	        // 箱号已释放，可登记新残损案
215	        long nextCase = newCase("TEMU1000007", "10000.00");
216	        assertThat(nextCase).isNotEqualTo(caseId);
217	    }
