package com.example.starter.damage.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 修箱密封报价与供应商资格请求报文集合。
 * 所有新增写操作均携带 requestId（幂等）与 expectedVersion（乐观版本，从 1 开始）。
 * 时刻字段一律为 UTC。
 */
public final class SealedRequests {

    private SealedRequests() {
    }

    /**
     * 发布询价版本：固定残损项集合与每项允许工法、UTC 报价截止时刻。
     * expectedVersion 必须等于该案件下一个询价版本号（首次为 1）。
     */
    public record PublishInquiryRequest(
            @NotBlank String requestId,
            @NotNull Integer expectedVersion,
            @NotNull LocalDateTime deadline,
            @NotEmpty List<@Valid InquiryItemInput> items) {
    }

    /** 询价残损项：引用原案残损项 ID 及该项允许工法集合（顺序即报价项序号，从 1 开始） */
    public record InquiryItemInput(
            @NotNull Long itemId,
            @NotEmpty List<@NotBlank String> allowedMethods) {
    }

    /** 提交/修订报价：一供应商一询价版本仅一个当前报价，须按序号覆盖全部项 */
    public record SubmitBidRequest(
            @NotBlank String requestId,
            @NotBlank String supplierNo,
            @NotEmpty List<@Valid BidLineInput> lines) {
    }

    /** 报价分项：itemSeq 对应询价项序号，priceCents 为正整数分 */
    public record BidLineInput(
            @NotNull Integer itemSeq,
            @NotBlank String methodCode,
            @NotNull @Positive Long priceCents) {
    }

    /** 截止后开标请求 */
    public record OpenBidsRequest(@NotBlank String requestId) {
    }

    /** 中标双人不同复核请求；第二人复核通过即转原案修理批复 */
    public record ReviewRequest(
            @NotBlank String requestId,
            @NotBlank String reviewer) {
    }

    /** 供应商资格续期：新版本只追加，expectedVersion 为下一个资格版本号（首次为 1） */
    public record QualificationRenewRequest(
            @NotBlank String requestId,
            @NotNull Integer expectedVersion,
            @NotNull LocalDateTime validFrom,
            @NotNull LocalDateTime validUntil,
            @NotEmpty List<@NotBlank String> methods) {
    }

    /** 撤销供应商当前资格；批复后撤销只形成风险事件 */
    public record QualificationRevokeRequest(@NotBlank String requestId) {
    }
}

package com.example.starter.damage.dto;

import java.time.LocalDateTime;
import java.util.List;

/**
 * 修箱密封报价与供应商资格响应视图集合。
 * 开标清单、排除原因与复核记录均可复算，重复开标原样返回首次冻结结果。
 */
public final class SealedViews {

    private SealedViews() {
    }

    /** 询价残损项视图（固定快照） */
    public record InquiryItemView(
            int itemSeq,
            long caseItemId,
            String iiclCode,
            String component,
            List<String> allowedMethods) {
    }

    /** 询价版本视图 */
    public record InquiryView(
            long id,
            long caseId,
            int version,
            LocalDateTime deadline,
            String status,
            LocalDateTime openedAt,
            Long approvalId,
            List<InquiryItemView> items) {
    }

    /** 报价分项视图 */
    public record BidLineView(
            int itemSeq,
            String methodCode,
            long priceCents) {
    }

    /** 报价版本视图（含历史修订时由列表给出） */
    public record BidView(
            long id,
            long inquiryId,
            String supplierNo,
            int revision,
            long totalCents,
            String status,
            String result,
            String exclusionReason,
            Long qualificationId,
            List<BidLineView> lines) {
    }

    /** 开标清单行：含中标/落标/排除及原因，按总价、供应商编号排序 */
    public record OpeningBidView(
            long bidId,
            String supplierNo,
            int revision,
            long totalCents,
            String result,
            String exclusionReason) {
    }

    /**
     * 开标结果视图（首次开标冻结，重复开标原样返回）。
     * status：SELECTED 已选定中标 / NO_VALID_BID 零有效报价。
     * converted：双人不同复核完成并已转原案修理批复。
     */
    public record OpeningView(
            long id,
            long inquiryId,
            int inquiryVersion,
            long caseId,
            String status,
            Long winnerBidId,
            String winnerSupplierNo,
            Long totalCents,
            Long approvalId,
            LocalDateTime openedAt,
            List<OpeningBidView> rankedBids,
            List<String> reviewers,
            boolean converted) {
    }

    /** 供应商资格版本视图 */
    public record QualificationView(
            long id,
            String supplierNo,
            int version,
            LocalDateTime validFrom,
            LocalDateTime validUntil,
            String status,
            LocalDateTime revokedAt,
            List<String> methods) {
    }

    /** 供应商视图（含当前最新资格版本，无则 null） */
    public record SupplierView(
            String supplierNo,
            String name,
            QualificationView currentQualification) {
    }

    /**
     * 撤销结果：REVOKED 资格已撤销冻结 / RISK_RECORDED 中标批复后撤销仅记风险事件。
     */
    public record RevokeResultView(
            String result,
            QualificationView qualification) {
    }
}

