        assertThat(inquiry.status()).isEqualTo("OPEN");
        assertThat(inquiry.items()).hasSize(2);
        assertThat(inquiry.items().get(0).allowedMethods()).containsExactly("HM", "WD");

        BidView sup100 = sealed.submitBid(pc.caseId(), 1,
