        sealed.submitBid(pc.caseId(), 1, bid("bid-b", "SUP-200", 1, 1, "WD", 200000, 2, "RP", 50000));

        // 开标前撤销 SUP-200（投标时资格有效）：开标竞争须与撤销一致
        RevokeResultView revoke = sealed.revokeQualification("SUP-200",
