        sealed.publishInquiry(pc.caseId(), wideInquiry("pub-404", 1, pc.item1(), pc.item2(), DEADLINE));
        assertThatThrownBy(() -> sealed.submitBid(pc.caseId(), 1,
                bid("bid-404", "SUP-999", 1, 1, "HM", 1, 2, "WD", 1)))
